const downloadButton = document.getElementById("download-btn");

// Named event handler function
function onDownloadClick(event) {
  console.log("Download initiated...");

  // Remove listener after first successful download
  downloadButton.removeEventListener("click", onDownloadClick);
  downloadButton.textContent = "Download Complete";
}

// Attach listener with { once: true } option (alternative to manual removal)
downloadButton.addEventListener("click", onDownloadClick, { once: true });

const outerCard = document.getElementById("card-container");
const innerButton = document.getElementById("favorite-star");

// Outer card click handler
outerCard.addEventListener("click", () => {
  console.log("Card clicked -> Navigating to product details page...");
});

// Inner star icon button handler
innerButton.addEventListener("click", (event) => {
  // STOP BUBBLING: Prevents the click from bubbling up to the outer card
  event.stopPropagation();

  console.log("Item added to favorites without navigating away!");
});

const listContainer = document.getElementById("todo-list");

// Attach ONLY ONE event listener on the parent container
listContainer.addEventListener("click", (event) => {
  // Check if the clicked target (or closest ancestor) is a delete button
  const deleteBtn = event.target.closest(".delete-item-btn");

  if (deleteBtn && listContainer.contains(deleteBtn)) {
    const listItem = deleteBtn.closest("li");
    const itemId = listItem.dataset.id;
    console.log(`Deleting item with ID: ${itemId}`);
    listItem.remove();
  }
});

const registrationForm = document.getElementById("signup-form");

registrationForm.addEventListener("submit", (event) => {
  // PREVENT DEFAULT: Stops the browser from executing its native form reload/POST navigation
  event.preventDefault();

  const emailInput = document.getElementById("user-email");

  if (!emailInput.value.includes("@")) {
    alert("Please provide a valid email address.");
    return;
  }

  // Perform asynchronous fetch API request without refreshing the page
  console.log("Submitting form data asynchronously via AJAX...");
});
